#include <cstring>
#include <vector>
#include <algorithm>
#define main original_unmodified_cli_main
#include "../rmsnorm-cuda/main.cu"
#undef main
static std::vector<float> readf(const char*name){FILE*f=fopen(name,"rb");if(!f)exit(2);fseek(f,0,SEEK_END);size_t n=ftell(f)/4;rewind(f);std::vector<float>v(n);if(fread(v.data(),4,n,f)!=n)exit(3);fclose(f);return v;}
int main(){const int G=16,R=20;const float guard=12345.25f;auto fixture=readf("fixtures_f32.bin");FILE*f=fopen("oracle_f64.bin","rb");if(!f)return 4;fseek(f,0,SEEK_END);size_t no=ftell(f)/8;rewind(f);std::vector<double>oracle(no);if(fread(oracle.data(),8,no,f)!=no)return 5;fclose(f);bool all=true;
 for(int trial=0;trial<=5;trial++){size_t fo=0,oo=0;bool ok=true;double maxerr=0;std::vector<float>prefix,outputs;std::vector<double>times;
 for(int shape=0;shape<2;shape++)for(int fixture_id=0;fixture_id<2;fixture_id++){int N=shape?5:7,H=shape?1027:1024,M=N*H;std::vector<float>xh(M+2*G,guard),gh(H+2*G,guard),oh(M+2*G,guard);std::copy_n(fixture.data()+fo,M,xh.data()+G);std::copy_n(fixture.data()+fo+M,H,gh.data()+G);fo+=M+H;
 for(int bt:{32,64,128,256,512,1024}){float*x,*g,*o;cudaMalloc(&x,xh.size()*4);cudaMalloc(&g,gh.size()*4);cudaMalloc(&o,oh.size()*4);cudaMemcpy(x,xh.data(),xh.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(g,gh.data(),gh.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(o,oh.data(),oh.size()*4,cudaMemcpyHostToDevice);auto launch=[&](){rmsnorm_forward(x+G,g+G,o+G,H,N,1e-5f,bt);};if(trial==0){launch();ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;cudaFree(x);cudaFree(g);cudaFree(o);continue;}std::vector<float>initial(oh.size()),xx(xh.size()),gg(gh.size()),out(oh.size());cudaMemcpy(initial.data(),o,initial.size()*4,cudaMemcpyDeviceToHost);ok &=initial==oh;cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<R;rep++)launch();ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R);cudaMemcpy(xx.data(),x,xx.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(gg.data(),g,gg.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(out.data(),o,out.size()*4,cudaMemcpyDeviceToHost);ok &=memcmp(xx.data(),xh.data(),xx.size()*4)==0&&memcmp(gg.data(),gh.data(),gg.size()*4)==0;for(int j=0;j<G;j++)ok &=out[j]==guard&&out[out.size()-G+j]==guard;for(int j=0;j<M;j++){double a=out[G+j],ref=oracle[oo+j],err=fabs(a-ref);maxerr=std::max(maxerr,err);ok &=std::isfinite(a)&&err<=1e-5+2e-6*fabs(ref);}prefix.insert(prefix.end(),xx.begin(),xx.end());prefix.insert(prefix.end(),gg.begin(),gg.end());prefix.insert(prefix.end(),initial.begin(),initial.end());outputs.insert(outputs.end(),out.begin(),out.end());cudaFree(x);cudaFree(g);cudaFree(o);
 }oo+=M;
 }if(!trial){if(!ok)return 6;continue;}all &=ok;std::vector<float>artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());char path[80];snprintf(path,80,"output_trial%d.bin",trial);f=fopen(path,"wb");if(!f)return 7;fwrite(artifact.data(),4,artifact.size(),f);fclose(f);double total=0;for(double t:times)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"sum24_twoscan_rms_kernel_hostwindows_R20\",\"jit_excluded\":true,\"path_times_seconds\":[",trial,total,ok?"true":"false",artifact.size(),maxerr);for(size_t j=0;j<times.size();j++)printf("%s%.12g",j?",":"",times[j]);printf("],\"internal_repeats\":20,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path,artifact.size());
 }puts(all?"PASS":"FAIL");return all?0:1;}
